-- V64에서 LAN-358 검수 완료 대표 예문 이미지 981개의 CloudFront URL을 Writing 표현에 반영한다.
-- 실행 전: manifest의 모든 S3 객체와 CloudFront 응답이 검증되었는지 확인한다.
SELECT pg_advisory_xact_lock(hashtext('lan358-representative-image-urls'));
LOCK TABLE writing_expression IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE lan358_representative_image_updates (
    expression_id BIGINT PRIMARY KEY,
    image_url VARCHAR(500) NOT NULL
) ON COMMIT DROP;


DO $$
BEGIN
    IF (SELECT COUNT(*) FROM lan358_representative_image_updates) <> 981 THEN
        RAISE EXCEPTION 'LAN-358 representative image manifest must contain 981 rows';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM lan358_representative_image_updates source
        LEFT JOIN writing_expression target ON target.id = source.expression_id
        WHERE target.id IS NULL
    ) THEN
        RAISE EXCEPTION 'LAN-358 representative image target expression is missing';
    END IF;
END
$$;

UPDATE writing_expression target
SET representative_image_url = source.image_url,
    updated_at = CURRENT_TIMESTAMP
FROM lan358_representative_image_updates source
WHERE target.id = source.expression_id
  AND target.representative_image_url IS DISTINCT FROM source.image_url;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM lan358_representative_image_updates source
        JOIN writing_expression target ON target.id = source.expression_id
        WHERE target.representative_image_url IS DISTINCT FROM source.image_url
    ) THEN
        RAISE EXCEPTION 'LAN-358 representative image URL update verification failed';
    END IF;
END
$$;
